<?php require_once __DIR__.'/../includes/auth.php';if(current_user()&&current_user()['role']==='admin'){header('Location:index.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$pdo->prepare("SELECT * FROM users WHERE email=? AND role='admin' LIMIT 1");$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u&&$u['status']==='active'&&password_verify($_POST['password'],$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];header('Location:index.php');exit;}flash('error','Invalid admin credentials.');}$f=take_flash();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZAIN STORE Admin Login</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body class="login-page"><div class="login-box"><a class="brand" href="../index.php">ZAIN STORE<span>.</span></a><h1 style="margin-top:25px">Admin access</h1><p style="color:#6b7280">Sign in to manage your entire store.</p><?php if($f):?><div class="admin-toast <?=$f[0]?>"><?=e($f[1])?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="field"><label>Email</label><input class="input" type="email" name="email" value="admin@luxora.test" required></div><div class="field"><label>Password</label><input class="input" type="password" name="password" value="Admin@123" required></div><button class="btn" style="width:100%">Sign in</button></form></div></body></html>
